const D = { energy: .6, scale: 1, breath: .6, grain: .45, drift: .3, hue: 205, x: .5, y: .5, style: 'film', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// ---------------------------------------------------------------------------
// Chest radiograph -- a PA plain film breathing on the viewbox. Soft-tissue
// grey torso, two radiolucent lung fields, the bright mediastinal shadow with
// the heart bulging left, a stacked bony spine, and nine pairs of ribs arcing
// out from the costovertebral joints. The whole cage inflates and empties on a
// slow respiratory cycle -- ribs elevate, lungs expand, the diaphragm domes
// descend -- so the plate is never static. Film grey, warm bromide, a cool
// digital plate, or a blueprint of bone contours.
// ---------------------------------------------------------------------------
const sd = P.seed | 0;
const fr = i => { const s = Math.sin(i * 127.1 + sd * 311.7) * 43758.5453; return s - Math.floor(s); };

if (!S.g || S.gw !== width) {
  S.g = createGraphics(Math.max(360, Math.min(900, Math.round(width / 1.8))), Math.max(360, Math.min(900, Math.round(width / 1.8)) * height / width | 0));
  S.g.pixelDensity(1); S.gw = width;
  // film-grain tile
  const gw = S.g.width, gh = S.g.height;
  S.grain = createGraphics(gw, gh); S.grain.pixelDensity(1);
  const gr = S.grain; gr.loadPixels(); const gp = gr.pixels;
  for (let k = 0; k < gw * gh; k++) { const v = (fr(k * 1.7) - 0.5); const o = 4 * k; gp[o] = gp[o + 1] = gp[o + 2] = 128 + v * 150; gp[o + 3] = 255; }
  gr.updatePixels();
}
const g = S.g, GW = g.width, GH = g.height, u = Math.min(GW, GH);

// respiratory cycle: two incommensurate slow terms -> never re-phases near 8 s
const br = 0.5 + 0.5 * (0.62 * Math.sin(K.t * 0.42 + 0.4) + 0.38 * Math.sin(K.t * 0.73 * (0.6 + P.drift) + 2.1));
const inh = br * (0.6 + P.breath);              // inflation amount
const gain = 0.62 + P.energy * 0.7 + A.rms * 0.2;
const style = P.style, blue = P.hue > 250 || P.hue < 30;

const mag = Math.max(1, P.scale);
const cx = GW * 0.5, cy = GH * 0.5;
g.push();
g.translate(GW / 2, GH / 2); g.scale(mag); g.translate(-GW / 2, -GH / 2);
g.translate((0.5 - P.x) * GW, (0.5 - P.y) * GH);

// ---- tone helpers ----
const bg = style === 'schematic' ? [215, 60, 10] : [0, 0, style === 'warm' ? 6 : 7];
g.background(bg[0], bg[1], bg[2]);
function tone(v) { // map density 0..1 -> HSB colour for the chosen film
  v = Math.max(0, Math.min(1, v * gain));
  if (style === 'warm') return [32, 22 - v * 14, 8 + v * 86];
  if (style === 'cool') return [205, 30 - v * 20, 6 + v * 88];
  if (style === 'schematic') return [205, 55, 20 + v * 78];
  return [210, 5, 6 + v * 88];                 // film neutral grey
}
function T(v, a) { const c = tone(v); g.fill(c[0], c[1], c[2], a == null ? 100 : a); }

const chestW = u * 0.40, chestTop = GH * 0.20 - inh * u * 0.02, chestBot = GH * 0.86 + inh * u * 0.01;
const schem = style === 'schematic';

if (!schem) {
  // soft-tissue torso silhouette
  g.noStroke(); T(0.34);
  g.beginShape();
  g.vertex(cx - chestW * 1.02, chestTop + u * 0.02);
  g.bezierVertex(cx - chestW * 1.2, GH * 0.5, cx - chestW * 1.05, chestBot, cx - chestW * 0.7, chestBot + u * 0.02);
  g.vertex(cx + chestW * 0.7, chestBot + u * 0.02);
  g.bezierVertex(cx + chestW * 1.05, chestBot, cx + chestW * 1.2, GH * 0.5, cx + chestW * 1.02, chestTop + u * 0.02);
  g.bezierVertex(cx + chestW * 0.5, chestTop - u * 0.04, cx - chestW * 0.5, chestTop - u * 0.04, cx - chestW * 1.02, chestTop + u * 0.02);
  g.endShape(CLOSE);
  // shoulders (denser)
  T(0.42); g.ellipse(cx - chestW * 0.95, chestTop + u * 0.05, u * 0.32, u * 0.26);
  g.ellipse(cx + chestW * 0.95, chestTop + u * 0.05, u * 0.32, u * 0.26);
  // lung fields (radiolucent, darker) — expand with inhale
  const lw = chestW * (0.66 + inh * 0.12), lh = (chestBot - chestTop) * (0.62 + inh * 0.05);
  const lyc = chestTop + lh * 0.52;
  T(0.13); g.ellipse(cx - chestW * 0.52, lyc, lw, lh);
  g.ellipse(cx + chestW * 0.52, lyc, lw * 0.94, lh);   // right lung slightly larger footprint
  // mediastinum + heart shadow (bright soft tissue), heart bulges left
  T(0.5); g.rect(cx - chestW * 0.13, chestTop, chestW * 0.26, chestBot - chestTop, chestW * 0.1);
  T(0.46);
  g.beginShape();
  g.vertex(cx - chestW * 0.05, GH * 0.44);
  g.bezierVertex(cx - chestW * 0.62, GH * 0.5, cx - chestW * 0.55, GH * 0.72, cx - chestW * 0.06, GH * 0.72);
  g.vertex(cx + chestW * 0.24, GH * 0.72);
  g.bezierVertex(cx + chestW * 0.34, GH * 0.6, cx + chestW * 0.2, GH * 0.46, cx - chestW * 0.05, GH * 0.44);
  g.endShape(CLOSE);
  // diaphragm domes (bright), descend on inhale
  const dY = chestBot - lh * (0.06 - inh * 0.05);
  T(0.5); g.ellipse(cx - chestW * 0.5, dY, lw * 1.02, lh * 0.5);
  g.ellipse(cx + chestW * 0.5, dY - u * 0.02, lw, lh * 0.52);
  // abdomen below
  T(0.4); g.rect(cx - chestW, chestBot, chestW * 2, GH - chestBot + 2);
}

// ---- BONES (additive over soft tissue) ----
g.blendMode(schem ? BLEND : ADD);
const boneV = schem ? 0.9 : 0.62;
// spine: stacked vertebral bodies down the midline
const nvert = 13, vtop = chestTop - u * 0.02, vbot = chestBot + u * 0.05, vsp = (vbot - vtop) / nvert;
for (let k = 0; k < nvert; k++) {
  const vy = vtop + k * vsp + Math.sin(k) * 0.0;
  if (schem) { g.noFill(); g.stroke(tone(boneV)[0], tone(boneV)[1], tone(boneV)[2]); g.strokeWeight(u * 0.004); g.rect(cx - chestW * 0.09, vy, chestW * 0.18, vsp * 0.8, vsp * 0.16); }
  else { g.noStroke(); T(boneV * 0.9, 70); g.rect(cx - chestW * 0.095, vy, chestW * 0.19, vsp * 0.82, vsp * 0.18); T(boneV * 0.4, 40); g.rect(cx - chestW * 0.095, vy + vsp * 0.82, chestW * 0.19, vsp * 0.18); }
}
// clavicles
g.noFill(); g.stroke(tone(boneV)[0], tone(boneV)[1], tone(boneV)[2]); g.strokeWeight(u * (schem ? 0.006 : 0.014));
for (let s = -1; s <= 1; s += 2) {
  g.bezier(cx + s * chestW * 0.06, chestTop + u * 0.02, cx + s * chestW * 0.45, chestTop - inh * u * 0.015, cx + s * chestW * 0.8, chestTop + u * 0.01, cx + s * chestW * 0.98, chestTop + u * 0.05);
}
// ribs: nine pairs arcing from spine, elevating with inhale
const nrib = 9, rtop = chestTop + u * 0.03, rsp = (chestBot - chestTop) * 0.072;
for (let s = -1; s <= 1; s += 2) {
  for (let k = 0; k < nrib; k++) {
    const jit = (fr(k * 3.1 + s) - 0.5) * u * 0.004;
    const y0 = rtop + k * rsp - inh * u * 0.02 * (1 - k / nrib) + jit;         // costovertebral, elevates
    const arch = u * (0.05 + 0.02 * Math.sin(k * 0.6)) * (0.8 + inh * 0.5);
    const spread = chestW * (0.9 + k * 0.02);
    const dip = u * 0.05 + k * u * 0.006;
    g.strokeWeight(u * (schem ? 0.0035 : 0.0075) * (1 - k * 0.02));
    // posterior rib: bows upward then sweeps down laterally
    g.bezier(cx + s * chestW * 0.11, y0, cx + s * spread * 0.5, y0 - arch, cx + s * spread * 0.92, y0 + dip * 0.3, cx + s * spread * 1.02, y0 + dip);
    if (!schem && k < 7) {   // faint anterior rib angling down toward the sternum
      g.strokeWeight(u * 0.004);
      const c = tone(boneV * 0.55); g.stroke(c[0], c[1], c[2]);
      g.bezier(cx + s * spread * 1.0, y0 + dip, cx + s * spread * 0.6, y0 + dip + u * 0.03, cx + s * chestW * 0.4, y0 + dip + u * 0.06, cx + s * chestW * 0.12, y0 + dip + u * 0.075);
      g.stroke(tone(boneV)[0], tone(boneV)[1], tone(boneV)[2]);
    }
  }
}
g.noStroke();
g.blendMode(BLEND);
g.pop();

// film grain over the whole plate
if (!schem) {
  g.push(); g.blendMode(MULTIPLY); g.tint(0, 0, 100, 18 + P.grain * 42); g.image(S.grain, 0, 0); g.pop();
}
// edge vignette (thick dark border strokes darken only the margins)
g.push(); g.rectMode(CENTER); g.noFill(); g.blendMode(MULTIPLY);
for (let r = 0; r < 3; r++) { g.stroke(0, 0, 0, 22); g.strokeWeight(u * 0.05 * (3 - r)); g.rect(GW / 2, GH / 2, GW - u * 0.02 - r * u * 0.06, GH - u * 0.02 - r * u * 0.06); }
g.pop();

push();
if (P.alpha < 100) tint(0, 0, 100, P.alpha);
image(g, 0, 0, width, height);
pop();
blendMode(BLEND);
drawingContext.shadowBlur = 0;
